from pathlib import Path
import sys,json
B=Path('engineering/security-owner-privacy-m2-20261021');E=Path('engineering/security-m2-final-acceptance-20261021');sys.path.insert(0,str(B.resolve()));from capture_catalog import query
r=query("BEGIN READ ONLY;SET LOCAL statement_timeout='15s';SELECT count(*) messages,count(*) FILTER (WHERE attachment_url IS NOT NULL) attachment_urls,count(*) FILTER (WHERE attachment_url LIKE '%/storage/v1/object/public/%') public_storage_urls,count(*) FILTER (WHERE attachment_path IS NOT NULL) attachment_paths FROM public.meeting_room_messages;ROLLBACK;");(E/'ATTACHMENT-AGGREGATES.json').write_text(json.dumps(r,indent=2));print(json.dumps(r))
r=query("BEGIN READ ONLY;SET LOCAL statement_timeout='15s';SELECT o.metadata->>'mimetype' mime,count(*) objects,count(*) FILTER (WHERE EXISTS (SELECT 1 FROM public.meeting_room_messages m WHERE m.attachment_path=o.name OR m.attachment_url LIKE '%'||o.name)) matching_meeting_attachments FROM storage.objects o WHERE o.metadata->>'mimetype' IN ('application/pdf','application/vnd.openxmlformats-officedocument.wordprocessingml.document') GROUP BY 1;ROLLBACK;");(E/'PUBLIC-DOCUMENT-REFERENCES.json').write_text(json.dumps(r,indent=2));print(json.dumps(r))
